mapper.select:
SELECT schema_version AS schemaVersion,
       catalog_json::text AS catalogJson,
       updated_at AS updatedAt
FROM public.wasm_catalog_sources
WHERE game_id = #{gameId}
  AND updated_at > #{updatedAfter}

mapper.update:
UPDATE public.wasm_catalog_sources
SET start_version_id = #{versionId},
    end_version_id = #{versionId}
WHERE game_id = #{gameId}
